use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (left: Vec<i32>, right: Vec<i32>)
    ensures
        // Concatenation equals the original sequence, preserving order.
        left@ + right@ == a@,

        // Lengths add up to the original length.
        left@.len() + right@.len() == a@.len(),

        // Lengths match the chosen mid exactly.
        left@.len() == (if a@.len() <= 1 { a@.len() } else { a@.len() / 2 }),
        right@.len() == a@.len() - (if a@.len() <= 1 { a@.len() } else { a@.len() / 2 }),

        // When the input has more than one element, both outputs are strictly shorter.
        a@.len() > 1 ==> (0 < left@.len() && left@.len() < a@.len()),
        a@.len() > 1 ==> (0 < right@.len() && right@.len() < a@.len()),
{
    let n = a.len();

    // Choose a split point that guarantees, when n > 1:
    // 0 < mid < n, so both parts are strictly shorter than the original.
    let mid = if n <= 1 { n } else { n / 2 };

    // Help the verifier relate `mid` computed from `n` to the same expression over `a@.len()`.
    assert(n as nat == a@.len());

    // Bounds needed for split_off.
    assert(mid <= n);
    if n > 1 {
        assert(0 < mid);
        assert(mid < n);
    }

    // split_off keeps order:
    // - `left` becomes a[0..mid]
    // - returned `right` is a[mid..n]
    let mut left = a;
    let right = left.split_off(mid);

    // `split_off` spec yields: old(left) == left + right, i.e., a@ == left@ + right@
    (left, right)
}

}

